package dev.gdal4k

import dev.gdal4k.internal.*
import dev.gdal4k.runtime.*
import kotlinx.coroutines.*
import kotlinx.coroutines.test.runTest
import kotlinx.serialization.json.*
import kotlin.test.*

class VectorColumnsControlTest {
    private fun metadata(kind: String = "long", rows: Int = 1): JsonElement = Json.parseToJsonElement(
        """{"rows":$rows,"columns":[{"name":"value","kind":"$kind","geometry":false}]}""")

    @Test fun decoderPreservesSignedIntegerBitsNullsAndUtf8() = runTest {
        // Wire bytes are independent constants, not generated by the codec being verified.
        val min = byteArrayOf(1, 0, 0, 0, 0, 0, 0, 0, -128, 0)
        val column = requireNotNull(decodeColumnBatch(metadata(rows = 2), min)).columns.single() as FeatureColumn.Longs
        assertEquals(Long.MIN_VALUE, column.values[0]); assertContentEquals(booleanArrayOf(true, false), column.valid)
        val text = "한글 😀".encodeToByteArray()
        val bytes = byteArrayOf(1, text.size.toByte(), 0, 0, 0) + text
        val string = requireNotNull(decodeColumnBatch(metadata("string"), bytes)).columns.single() as FeatureColumn.Strings
        assertEquals("한글 😀", string.values[0])
    }
    @Test fun malformedPayloadCannotReturnPartialColumnBatch() = runTest {
        for (bytes in listOf(byteArrayOf(1), byteArrayOf(2), byteArrayOf(0, 0))) assertFails { decodeColumnBatch(metadata(), bytes) }
        assertFails { decodeColumnBatch(metadata(rows = -1), byteArrayOf(0)) }
        assertFails { decodeColumnBatch(metadata("unknown"), byteArrayOf(0)) }
        assertFails { decodeColumnBatch(metadata("string"), byteArrayOf(1, -1, -1, -1, -1)) }
        assertFails { decodeColumnBatch(metadata("string"), byteArrayOf(1, 2, 0, 0, 0, 65)) }
        assertFails { decodeColumnBatch(metadata("string"), byteArrayOf(1, 1, 0, 0, 0, -1)) }
        assertFails { decodeColumnBatch(JsonNull, byteArrayOf(0)) }
        assertNull(decodeColumnBatch(JsonNull, byteArrayOf()))
    }
    @Test fun oldEngineRejectsColumnOpenBeforeAnyTransportOrCursorChange() = runTest {
        var calls = 0
        val engine = RuntimeEngine(object : GdalTransport {
            override val supportsBinaryCoordinates = true
            override val supportsBinaryRaster = true
            override suspend fun call(request: String, attachment: Any?, control: GdalCallControl?): String { calls++; error("unexpected") }
            override suspend fun close() {}
        })
        assertFails { BundledLayer(engine, "1", null).openColumnStream(1) }
        assertEquals(0, calls); engine.close()
    }
    @Test fun queuedCancellationDoesNotReadAndClosesStreamAfterReleasingEngineLock() = runTest {
        val entered = CompletableDeferred<Unit>(); val release = CompletableDeferred<Unit>()
        var reads = 0; var closes = 0
        val engine = RuntimeEngine(object : GdalTransport {
            override val supportsBinaryColumns = true
            override suspend fun call(request: String, attachment: Any?, control: GdalCallControl?): String {
                if (request.contains("\"close\"")) closes++
                else { entered.complete(Unit); release.await() }
                return """{"result":{"value":null}}"""
            }
            override suspend fun callBinary(request: String, input: ByteArray?, control: GdalCallControl?): GdalBinaryReply { reads++; error("unexpected") }
            override suspend fun close() {}
        })
        val first = launch { engine.invoke("Handle", "2", "wait", emptyMap()) }; entered.await()
        val waiting = launch(start = CoroutineStart.UNDISPATCHED) { BundledFeatureColumnStream(engine, "3", null).read() }
        waiting.cancel(); release.complete(Unit); first.join(); waiting.join()
        assertTrue(waiting.isCancelled); assertEquals(0, reads); assertEquals(1, closes); engine.close()
    }
}
